<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
import { useI18n } from 'vue-i18n';
import type { PublicCategory, PublicProduct, PublicStore } from '../../../types';
import EmptyState from '../components/EmptyState.vue';
import ProductGrid from '../components/ProductGrid.vue';
import PublicPagination from '../components/PublicPagination.vue';
import SearchBar from '../components/SearchBar.vue';
import EssentialLayout from '../EssentialLayout.vue';
interface Paginator { data: PublicProduct[]; links: Array<{ url: string | null; label: string; active: boolean }>; current_page: number; last_page: number; total: number }
defineProps<{ store: PublicStore; products: Paginator; categories: PublicCategory[]; filters: { search: string | null; category: string | null } }>();
const { t } = useI18n();
</script>
<template><Head :title="t('storefront.catalog')"><meta head-key="robots" name="robots" :content="filters.search ? 'noindex,follow' : 'index,follow'" /></Head><EssentialLayout :store="store"><div class="mx-auto max-w-[1440px] px-4 py-8 sm:px-6 lg:px-8"><nav class="text-sm text-slate-500" :aria-label="t('common.breadcrumb')"><Link :href="`/tienda/${store.publicHandle}`">{{ t('storefront.home') }}</Link><span aria-hidden="true"> / </span><span class="text-slate-800">{{ t('storefront.catalog') }}</span></nav><div class="mt-6 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><h1 class="text-3xl font-bold tracking-tight sm:text-4xl">{{ filters.category ? categories.find((category) => category.slug === filters.category)?.name : t('storefront.catalogTitle') }}</h1><p class="mt-2 text-slate-600">{{ t('storefront.results', { count: products.total }) }}</p></div><div class="w-full lg:max-w-md"><SearchBar :action="`/tienda/${store.publicHandle}/productos`" :initial-value="filters.search" /></div></div><nav v-if="categories.length" class="-mx-4 mt-7 flex gap-2 overflow-x-auto px-4 pb-2 sm:mx-0 sm:px-0" :aria-label="t('storefront.categories')"><Link :href="`/tienda/${store.publicHandle}/productos`" class="flex min-h-11 shrink-0 items-center rounded-full border px-4 text-sm font-semibold" :class="!filters.category ? 'border-[var(--sf-primary)] bg-[var(--sf-primary)] text-white' : 'border-[var(--sf-border)] bg-white'">{{ t('storefront.all') }}</Link><Link v-for="category in categories" :key="category.slug" :href="category.url" class="flex min-h-11 shrink-0 items-center rounded-full border px-4 text-sm font-semibold" :class="filters.category === category.slug ? 'border-[var(--sf-primary)] bg-[var(--sf-primary)] text-white' : 'border-[var(--sf-border)] bg-white'">{{ category.name }}</Link></nav><div class="mt-8"><ProductGrid v-if="products.data.length" :products="products.data" :locale="store.locale" /><EmptyState v-else :title="t('storefront.noResultsTitle')" :description="t('storefront.noResultsDescription')"><Link :href="`/tienda/${store.publicHandle}/productos`" class="mt-5 inline-flex min-h-11 items-center rounded-lg bg-[var(--sf-primary)] px-5 font-semibold text-white">{{ t('storefront.clearSearch') }}</Link></EmptyState></div><PublicPagination class="mt-10" :links="products.links" :current-page="products.current_page" :last-page="products.last_page" /></div></EssentialLayout></template>
